describe("jobs/digest-email-job", () => {
  it("uses the org's configured digest hour to pick the window", async () => {
    const now = nowAtHour(1);
    const tenant = await makeTenant("digest-window", 1);
    await subscribeToDigest(tenant);

    await insertNotificationAt(tenant, new Date(now.getTime() - 12 * 3_600_000), "Recent update");
    await insertNotificationAt(tenant, new Date(now.getTime() - 30 * 3_600_000), "Stale update");

    const sendSpy = vi.spyOn(emailService, "sendEmail").mockResolvedValue(undefined);

    await runDigestEmailJob(now);

    expect(sendSpy).toHaveBeenCalledTimes(1);
    const html = sendSpy.mock.calls[0]?.[0].html ?? "";
    expect(cell(html, "entryCount")).toBe("1");
    expect(cell(html, "headline")).toBe("Recent update");
  });

  it("skips an org whose digest hour has not arrived", async () => {
    const tenant = await makeTenant("digest-hour-not-yet", 2);
    await subscribeToDigest(tenant);
    await insertNotificationAt(tenant, new Date(nowAtHour(2).getTime() - 3_600_000), "Fresh");

    const sendSpy = vi.spyOn(emailService, "sendEmail").mockResolvedValue(undefined);

    // A run at an hour that does not match the org's configured hour.
    await runDigestEmailJob(nowAtHour(3));

    expect(sendSpy).not.toHaveBeenCalled();
  });

  it("skips an org whose plan does not include digest_email", async () => {
    const now = nowAtHour(4);
    const tenant = await makeTenant("digest-free-plan", 4, "free");
    await subscribeToDigest(tenant);
    await insertNotificationAt(tenant, new Date(now.getTime() - 3_600_000), "Fresh");

    const sendSpy = vi.spyOn(emailService, "sendEmail").mockResolvedValue(undefined);

    await runDigestEmailJob(now);

    expect(sendSpy).not.toHaveBeenCalled();
  });

  it("sends nothing to a recipient with an empty window", async () => {
    const now = nowAtHour(5);
    const tenant = await makeTenant("digest-empty-window", 5);
    await subscribeToDigest(tenant);
    // Nothing unread inside the window at all.

    const sendSpy = vi.spyOn(emailService, "sendEmail").mockResolvedValue(undefined);

    const result = await runDigestEmailJob(now);

    expect(sendSpy).not.toHaveBeenCalled();
    expect(result.processed).toBe(0);
  });

  it("caps the entries at DIGEST_MAX_ENTRIES", async () => {
    const now = nowAtHour(6);
    const tenant = await makeTenant("digest-cap", 6);
    await subscribeToDigest(tenant);

    for (let i = 0; i < DIGEST_MAX_ENTRIES + 5; i += 1) {
      await insertNotificationAt(
        tenant,
        new Date(now.getTime() - (i + 1) * 1_000),
        `Update ${i}`,
      );
    }

    const sendSpy = vi.spyOn(emailService, "sendEmail").mockResolvedValue(undefined);

    await runDigestEmailJob(now);

    expect(sendSpy).toHaveBeenCalledTimes(1);
    const html = sendSpy.mock.calls[0]?.[0].html ?? "";
    expect(cell(html, "entryCount")).toBe(String(DIGEST_MAX_ENTRIES));
  });

  it("does not resend a digest for an already-covered window", async () => {
    const now = nowAtHour(7);
    const tenant = await makeTenant("digest-no-resend", 7);
    await subscribeToDigest(tenant);
    await insertNotificationAt(tenant, new Date(now.getTime() - 3_600_000), "Once");

    const sendSpy = vi.spyOn(emailService, "sendEmail").mockResolvedValue(undefined);

    await runDigestEmailJob(now);
    expect(sendSpy).toHaveBeenCalledTimes(1);

    await runDigestEmailJob(now);
    expect(sendSpy).toHaveBeenCalledTimes(1);
  });

  it("constructs its own actor rather than reading cookies", async () => {
    const now = nowAtHour(8);
    const tenant = await makeTenant("digest-own-actor", 8);
    await subscribeToDigest(tenant);
    await insertNotificationAt(tenant, new Date(now.getTime() - 3_600_000), "Owns its actor");

    vi.spyOn(emailService, "sendEmail").mockResolvedValue(undefined);
    const contextSpy = vi.spyOn(featureFlagService, "buildFlagContext");

    await runDigestEmailJob(now);

    expect(contextSpy).toHaveBeenCalledWith(
      null,
      expect.objectContaining({ id: tenant.org.id }),
    );
  });
});
/** Relative formatting, overdue detection and the digest window. */
import { describe, expect, it } from "vitest";
import {
  addDays,
  digestWindow,
  formatDate,
  formatRelative,
  isOverdue,
  now,
  parseIso,
} from "@/lib/date";
import type { IsoTimestamp } from "@/types/common";

const REFERENCE = new Date("2026-03-15T12:00:00.000Z");
const iso = (value: string): IsoTimestamp => value as IsoTimestamp;

describe("lib/date", () => {
  it("round-trips now() through parseIso()", () => {
    const stamp = now();
    expect(parseIso(stamp).toISOString()).toBe(stamp);
  });

  it("throws on a malformed timestamp rather than yielding Invalid Date", () => {
    expect(() => parseIso(iso("not-a-date"))).toThrow(RangeError);
  });

  it("formats past distances with an 'ago' suffix", () => {
    expect(formatRelative(iso("2026-03-15T11:59:30.000Z"), REFERENCE)).toBe("just now");
    expect(formatRelative(iso("2026-03-15T11:55:00.000Z"), REFERENCE)).toBe("5 minutes ago");
    expect(formatRelative(iso("2026-03-15T11:00:00.000Z"), REFERENCE)).toBe("1 hour ago");
    expect(formatRelative(iso("2026-03-13T12:00:00.000Z"), REFERENCE)).toBe("2 days ago");
    expect(formatRelative(iso("2026-03-01T12:00:00.000Z"), REFERENCE)).toBe("2 weeks ago");
  });

  it("formats future distances with an 'in' prefix", () => {
    expect(formatRelative(iso("2026-03-15T12:30:00.000Z"), REFERENCE)).toBe("in 30 minutes");
    expect(formatRelative(iso("2026-03-18T12:00:00.000Z"), REFERENCE)).toBe("in 3 days");
  });

  it("renders an absolute date in the requested timezone", () => {
    expect(formatDate(iso("2026-03-15T23:30:00.000Z"))).toBe("15 Mar 2026");
    expect(formatDate(iso("2026-03-15T23:30:00.000Z"), "Asia/Tokyo")).toBe("16 Mar 2026");
  });

  it("treats a null due date as never overdue", () => {
    expect(isOverdue(null, REFERENCE)).toBe(false);
    expect(isOverdue(iso("2026-03-15T11:59:59.000Z"), REFERENCE)).toBe(true);
    expect(isOverdue(iso("2026-03-15T12:00:01.000Z"), REFERENCE)).toBe(false);
  });

  it("adds and subtracts whole days", () => {
    expect(addDays(iso("2026-03-15T12:00:00.000Z"), 3)).toBe("2026-03-18T12:00:00.000Z");
    expect(addDays(iso("2026-03-01T12:00:00.000Z"), -1)).toBe("2026-02-28T12:00:00.000Z");
  });

  it("ends the digest window at today's digest hour once it has passed", () => {
    const window = digestWindow(8, REFERENCE);
    expect(window.end).toBe("2026-03-15T08:00:00.000Z");
    expect(window.start).toBe("2026-03-14T08:00:00.000Z");
  });

  it("falls back to yesterday's window when the digest hour has not arrived", () => {
    const window = digestWindow(20, REFERENCE);
    expect(window.end).toBe("2026-03-14T20:00:00.000Z");
    expect(window.start).toBe("2026-03-13T20:00:00.000Z");
  });

  it("rejects a digest hour outside 0-23", () => {
    expect(() => digestWindow(24, REFERENCE)).toThrow(RangeError);
    expect(() => digestWindow(-1, REFERENCE)).toThrow(RangeError);
  });
});
