    hour: Number(parts.hour) % 24,
    minute: Number(parts.minute),
    second: Number(parts.second),
  };
}

/** The zone's UTC offset (ms, east positive) at `epochMs`. */
function offsetAt(epochMs: number, timeZone: string): number {
  const wall = localFields(new Date(epochMs), timeZone);
  const asUtc = Date.UTC(
    wall.year,
    wall.month - 1,
    wall.day,
    wall.hour,
    wall.minute,
    wall.second,
  );
  const whole = epochMs - (((epochMs % 1000) + 1000) % 1000);
  return asUtc - whole;
}

/**
 * The instant at which the zone's clock shows `wallMs` (a wall time encoded
 * as if it were UTC). An ambiguous wall time (clocks going back) resolves to
 * the earlier instant; a skipped one (clocks going forward) resolves to the
 * instant the same distance past the transition — the first moment that
 * exists, for a time that falls exactly on the jump.
 */
function zonedWallTimeToUtc(wallMs: number, timeZone: string): number {
  const before = offsetAt(wallMs - DAY_MS, timeZone);
  const after = offsetAt(wallMs + DAY_MS, timeZone);
  const candidates = [wallMs - before, wallMs - after]
    .filter((instant) => instant + offsetAt(instant, timeZone) === wallMs)
    .sort((a, b) => a - b);
  if (candidates.length > 0) return candidates[0] as number;
  return wallMs - before;
}

function pad(value: number, width: number): string {
  const sign = value < 0 ? "-" : "";
  return sign + String(Math.abs(value)).padStart(width, "0");
}

/** The `YYYY-MM-DD` calendar date of `value` on the zone's clock. */
export function localDate(value: IsoTimestamp, timeZone: string): string {
  const wall = localFields(parseIso(value), timeZone);
  return `${pad(wall.year, 4)}-${pad(wall.month, 2)}-${pad(wall.day, 2)}`;
}

/**
 * The UTC instant at which the zone's calendar day containing `reference`
 * began.
 */
export function startOfLocalDay(reference: Date, timeZone: string): IsoTimestamp {
  const wall = localFields(reference, timeZone);
  return startOfLocalDate(wall.year, wall.month, wall.day, timeZone);
}

/**
 * Local midnight on the date `days` calendar days before `reference`'s local
 * date (negative `days` moves forward), as a UTC instant.
 */
export function startOfLocalDayDaysBefore(
  reference: Date,
  days: number,
  timeZone: string,
): IsoTimestamp {
  const wall = localFields(reference, timeZone);
  const shifted = new Date(Date.UTC(wall.year, wall.month - 1, wall.day) - days * DAY_MS);
  return startOfLocalDate(
    shifted.getUTCFullYear(),
    shifted.getUTCMonth() + 1,
    shifted.getUTCDate(),
    timeZone,
  );
}

function startOfLocalDate(
  year: number,
  month: number,
  day: number,
  timeZone: string,
): IsoTimestamp {
  const midnight = new Date(0);
  midnight.setUTCFullYear(year, month - 1, day);
  midnight.setUTCHours(0, 0, 0, 0);
  return toIsoTimestamp(new Date(zonedWallTimeToUtc(midnight.getTime(), timeZone)));
}
