grep -n "export" tests/server/_support/fixtures.ts | head; cat > tests/zz-tmp.test.ts <<'EOF'
import { afterAll, beforeAll, expect, it, vi } from "vitest";
vi.mock("@/lib/logger", async () => (await import("./server/_support/doubles/misc")).loggerModule);
import * as orgRepo from "@/server/repositories/organization-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import { updateOrganization } from "@/server/services/organization-service";
import { organizationSettingsSchema, updateOrganizationSchema } from "@/schemas/organization";
import { createTenant, issueInput, useTemporaryDatabase } from "./server/_support/fixtures";
let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); });
afterAll(() => cleanup());
it("works", async () => {
  const t = await createTenant("tz-check");
  expect(t.org.settings.timeZone).toBe("UTC");
  const u = await orgRepo.updateOrg(t.org.id, { orgId: t.org.id, settings: { timeZone: "Asia/Tokyo", digestHourUtc: 3 } });
  expect(u.settings.timeZone).toBe("Asia/Tokyo");
  await expect(orgRepo.updateOrg(t.org.id, { orgId: t.org.id, settings: { timeZone: "Nope/Zone", digestHourUtc: 9 } })).rejects.toBeInstanceOf(RangeError);
  await expect(updateOrganization(t.actors.owner, { orgId: t.org.id, settings: { timeZone: "Nope/Zone" } })).rejects.toBeInstanceOf(RangeError);
  const back = await orgRepo.findOrgById(t.org.id);
  expect(back?.settings.digestHourUtc).toBe(3);
  expect(back?.settings.timeZone).toBe("Asia/Tokyo");
  expect(organizationSettingsSchema.parse({}).timeZone).toBe("UTC");
  expect(organizationSettingsSchema.safeParse({ timeZone: "Nope/Zone" }).success).toBe(false);
  expect(updateOrganizationSchema.parse({ orgId: t.org.id, settings: { digestHourUtc: 4 } }).settings).toEqual({ digestHourUtc: 4 });
  const yesterday = new Date(Date.now() - 86_400_000 * 2).toISOString();
  const n = await issueRepo.nextIssueNumber(t.org.id, t.project.id);
  const i = await issueRepo.insertIssue(issueInput(t.org.id, t.project.id, { dueAt: yesterday }), t.userIds.owner, n);
  const n2 = await issueRepo.nextIssueNumber(t.org.id, t.project.id);
  const j = await issueRepo.insertIssue(issueInput(t.org.id, t.project.id, { dueAt: yesterday }), t.userIds.owner, n2);
  await issueRepo.setIssueStatus(t.org.id, j.id, "done");
  expect((await projectRepo.getProjectStats(t.org.id, t.project.id, "Asia/Tokyo")).overdueIssues).toBe(1);
  expect((await issueRepo.listOverdueIssues(t.org.id, new Date().toISOString() as never, "Asia/Tokyo")).map((x) => x.id)).toEqual([i.id]);
});
EOF
npx vitest run tests/zz-tmp.test.ts 2>&1 | grep -E "✓|×|Error|expected|Tests " | head -20; rm tests/zz-tmp.test.ts

